import { mkdir, readFile, rm, writeFile } from "node:fs/promises";
import path from "node:path";

/**
 * Where uploaded files (CV imports, later photos and exports) live. The api writes, the worker
 * reads; both get the same adapter from config. Keys are opaque, generated by the caller.
 */
export interface FileStorage {
  put(key: string, bytes: Uint8Array, contentType: string): Promise<void>;
  get(key: string): Promise<Uint8Array>;
  delete(key: string): Promise<void>;
}

export const FILE_STORAGE = Symbol.for("cvb.FileStorage");

const SAFE_KEY = /^[a-zA-Z0-9][a-zA-Z0-9/_.-]{0,255}$/;

function assertKey(key: string): void {
  if (!SAFE_KEY.test(key) || key.includes("..")) throw new Error(`Invalid storage key: ${key}`);
}

/** Stores files under one directory (a Docker volume shared by api and worker on the VPS). */
export class LocalDiskStorage implements FileStorage {
  constructor(private readonly root: string) {}

  private resolve(key: string): string {
    assertKey(key);
    const full = path.resolve(this.root, key);
    if (!full.startsWith(path.resolve(this.root) + path.sep)) throw new Error(`Invalid storage key: ${key}`);
    return full;
  }

  async put(key: string, bytes: Uint8Array, _contentType?: string): Promise<void> {
    const file = this.resolve(key);
    await mkdir(path.dirname(file), { recursive: true });
    await writeFile(file, bytes);
  }

  async get(key: string): Promise<Uint8Array> {
    return new Uint8Array(await readFile(this.resolve(key)));
  }

  async delete(key: string): Promise<void> {
    await rm(this.resolve(key), { force: true });
  }
}

/** For tests. */
export class InMemoryStorage implements FileStorage {
  readonly files = new Map<string, Uint8Array>();
  async put(key: string, bytes: Uint8Array, _contentType?: string) {
    assertKey(key);
    this.files.set(key, bytes);
  }
  async get(key: string) {
    const f = this.files.get(key);
    if (!f) throw new Error(`No file ${key}`);
    return f;
  }
  async delete(key: string) {
    this.files.delete(key);
  }
}
